import type { Filter } from "../shared/filters/types.js";
export type DatamineTimeUnit = "DAY" | "HOUR" | "MINUTE" | "MONTH" | "WEEK";
export type DatamineSchedule = {
    readonly kind: "fixed";
    readonly timeUnit: DatamineTimeUnit;
    readonly value: number;
    readonly description?: string;
} | {
    readonly kind: "cron";
    readonly cronExpression: string;
    readonly description?: string;
};
/** A rule-based datamine owned by its containing table. Column keys are
 * resolved to that table's field ids at build time. */
export interface TableDatamine<ColumnKey extends string = string> {
    readonly name: string;
    readonly primaryColumns: readonly [ColumnKey, ...ColumnKey[]];
    readonly description?: string;
    readonly filter?: Filter;
    readonly schedule?: DatamineSchedule;
    readonly limit?: number;
}
